#include "StdAfx.h"#include <math.h>#include "FscList.h"static char* sid = "Операция sqrt(x)";//AT-6//struct SLogic36  {  UINT I;// Вход  UINT O;// Выход  };//bool SFscList::FuncParser36( VAR_PARSER ){  FuncParserdo(fsc,p,dat,tmp);  SLogic36 io;  // Выходные точки  SDotValue O(enumValueDbl);  io.O = fsc->AddFscDots(&O);  // Входные точки  io.I = -1;  // Заказываем память  p.nBuff = fsc->AddFscBuff( &io, sizeof(io) );  //  ns_UT::SLocalTmp* item = tmp.Item();  item->nCount = 1;  item->dim[0] = io.O;  return true;}////void FuncDebugs36( VAR_DEBUGS )//  {//  strcat_s( str, sid );//  strcat_s( str, "\r\n------------------------------------------------------------\r\n" );//  FuncDebugsdo( p, str );//  }//void SFscList::FuncPaints36( VAR_PAINTS ){  SLogic36* dat = (SLogic36*)fsc->Data(p.nBuff);  //  CMyPen pen( font, p.Color( nSelect, dat->I, dat->O ) );  CMyBrush brush( font, 0x101010, true );  pen.Rect( p.rect );  font.Draw( p.rect, "SQRT" );}//void SFscList::FuncSetLnk36( VAR_SETLNK ){  // Вход только справа  if ( x == p.rect.right )     return;  SLogic36* dat = (SLogic36*)fsc->Data(p.nBuff);  dat->I = nLink;}////-----------------------------------------------------------------------------//UINT FuncCursor36( VAR_CURSOR )//  {//  SLogic36* dat = (SLogic36*)fsc->Data(p.nBuff);//  int x = (p.rect.left+p.rect.right)/2;//  return ( pt.x < x ) ? dat->I : dat->O;//  }////-----------------------------------------------------------------------------UINT* SFscList::FuncOutput36( VAR_OUTPUT ){  SLogic36* dat = (SLogic36*)fsc->Data(p.nBuff);  n = 1;  return &dat->O;}////-----------------------------------------------------------------------------void SFscList::FuncTimers36( VAR_TIMERS ){  SLogic36* dat = (SLogic36*)fsc->Data(p.nBuff);  SDotValue* O = fsc->DotV(dat->O);  if ( O->dwFlags & 1 )    return;  SDotValue* I = fsc->DotV(dat->I);  if ( I == NULL )    return;  double d = I->Dbl();  if ( d < 0 ) d = NaN;  else  d = sqrt(d);  O->Set( d );}////-----------------------------------------------------------------------------static LPCSTR s_pName[] = { "O" };int SFscList::FuncQuickWatch36( IFscStorage* fsc, LFscBase *obj, IFscStorage::SVarInfo *pvi, int cVI, LPCSTR *ppPntName ){  return 0;}int SFscList::SaveState36( IStateSer *psaver, IFscStorage* fsc, LFscBase *obj ){  SLogic36* dat = (SLogic36*)fsc->Data(obj->nBuff);  SDotValue* vals[] = { fsc->DotV(dat->O) };  for( int i=0; i<_countof(vals); ++i )  {    psaver->WriteDotV( vals[i], s_pName[i] );  }  return 0;}int SFscList::RestoreState36( IStateSer *prest, IFscStorage* fsc, LFscBase *obj ){  SLogic36* dat = (SLogic36*)fsc->Data(obj->nBuff);  SDotValue* vals[] = { fsc->DotV(dat->O) };  for( int i=0; i<_countof(vals); ++i )  {    prest->ReadDotV( vals[i], s_pName[i] );  }  return 0;}